// ── 工具函数 ──
// 控制台标识头：证明请求来自本控制台页面，而非外部网页冒用浏览器。
// 带自定义头的请求必须过 CORS 预检，天然挡住跨站脚本/表单的静默读取。
/** 数字加千分位（token 计数用）。 */
const fmtTok = (n) => (Number(n) || 0).toLocaleString('zh-CN');
/** 只有服务端明确给出的有限数字才算可显示；缺失、null、空值和错误形状保持未知。 */
function reportedNumber(value) {
  if (value == null || (typeof value === 'string' && value.trim() === '')) return null;
  if (typeof value !== 'number' && typeof value !== 'string') return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function reportedMetric(value, format = (number) => fmtTok(number)) {
  const number = reportedNumber(value);
  return number == null ? '取不到' : format(number);
}

