/** 记忆页状态条的一句话摘要（详情在「清理盘点」弹窗里）。 */
function memoryCleanupStatusText(result) {
  if (result?.ok !== true) return `失败：${String(result?.error || '服务端未确认盘点结果')}`;
  if (!Array.isArray(result.notApplicable) || !Array.isArray(result.notImplemented)) {
    return '盘点结果不完整：缺少 notApplicable / notImplemented 清单；不能确认清理状态。';
  }
  const activeCount = reportedNumber(result.scanned?.activeObservations);
  const active = activeCount == null ? '扫描条数取不到' : `已扫描 ${fmtTok(activeCount)} 条生效观察`;
  const changedText = result.apply?.requested === true
    ? `；本次已撤回 ${reportedMetric(result.apply?.changed)} 条`
    : '';
  // 分项契约是否可用：新模块的只读响应会带 `apply.selected`（旧档没有 ⇒ 按"不可执行"展示，不假装）。
  const bcTag = Array.isArray(result.apply?.selected) ? '可显式执行·会调模型' : '不可执行';
  return `只读盘点、不删任何东西：${active}；A 候选 ${reportedMetric(result.actions?.dedupeFuzzy?.candidates)} 对、`
    + `语义候选 ${reportedMetric(result.actions?.dedupeSemantic?.candidates)} 对（${bcTag}）、`
    + `C 候选 ${reportedMetric(result.actions?.refineTypes?.candidates)} 条（${bcTag}）${changedText}。详情见「清理盘点」弹窗。`;
}

function reportedTokens(value) {
  return reportedMetric(value, (number) => fmtTokens(number));
}

function reportedYuan(value) {
  return reportedMetric(value, (number) => fmtYuan(number));
}

function reportedPercent(value, digits = 0) {
  return reportedMetric(value, (number) => `${(number * 100).toFixed(digits)}%`);
}

function reportedListCount(value) {
  return Array.isArray(value) ? value.length : null;
}

function statusMetricLabels(status) {
  const usage = status?.usage || {};
  return {
    runs: reportedMetric(usage.runs, (number) => `${number}次`),
    tokens: reportedTokens(usage.totalTokens),
    searches: reportedMetric(status?.webSearchCount ?? usage.webSearchCount),
    // cacheHitRate = 综合口径（含主发言/判定/表情等全部调用）；主模型单独读数在 status.mainCacheHitRate
    cacheHitRate: reportedPercent(status?.cacheHitRate, 0),
    mainCacheHitRate: reportedPercent(status?.mainCacheHitRate, 1),
    cacheUsageCoverage: status?.cacheUsageCoverage && typeof status.cacheUsageCoverage === 'object'
      ? status.cacheUsageCoverage : null,
    cost: reportedYuan(status?.cost?.cost)
  };
}

const costGuardTokenSummary = (cost) => {
  if (cost?.truncated === true) return '今日用量暂不可信（统计可能偏小）';
  if (!cost || reportedNumber(cost.totalTokens) == null) return '今日 token 用量暂不可用';
  const max = reportedNumber(cost.dayTokenMax) == null
    ? '上限未提供'
    : Number(cost.dayTokenMax) === 0 ? '不限' : `上限 ${fmtTok(cost.dayTokenMax)} token`;
  return `今日 ${fmtTok(cost.totalTokens)} / ${max}`;
};

/**
 * 金额格式化（成本用）。
 * 成本经常是小额（几分钱），固定两位小数会全显示成 ¥0.00 看不出差别，
 * 所以小于 1 时多给两位有效数字。
 */
const fmtYuan = (n) => {
  const v = Number(n) || 0;
  if (v === 0) return '¥0';
  if (Math.abs(v) < 1) return `¥${v.toFixed(4)}`;
  return `¥${v.toFixed(2)}`;
};

