const TOOL_ACTION_WORDS = new Set([
  'start', 'begin', 'stop', 'end', 'reveal', 'get', 'fetch', 'query', 'search', 'find', 'list',
  'send', 'post', 'add', 'create', 'make', 'generate', 'remove', 'delete', 'update', 'set', 'check',
  'verify', 'read', 'write', 'save', 'load', 'open', 'close', 'run', 'execute', 'parse', 'download',
  'upload', 'convert', 'translate', 'analyze', 'summarize', 'export', 'import', 'reset', 'clear', 'move', 'play'
]);
function translateToolName(value) {
  const raw = String(value || '').split('__').pop()
    .replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
  const words = raw.split(/[^a-z0-9]+/).filter(Boolean);
  const action = words.find((w) => TOOL_ACTION_WORDS.has(w));
  const body = words.filter((w) => w !== action && TOOL_WORD_ZH[w] && !TOOL_ACTION_WORDS.has(w));
  const bodyZh = [...new Set(body.map((w) => TOOL_WORD_ZH[w]))].join('');
  if (action) return `${TOOL_WORD_ZH[action]}${bodyZh || '工具'}`;
  return bodyZh;
}
function toolDisplayName(id, preferred = '') {
  const raw = String(id || '');
  const fixed = TOOL_META[raw]?.name;
  if (fixed) return fixed;
  const preferredText = String(preferred || '').trim();
  if (preferredText && /[\u3400-\u9fff]/.test(preferredText)) return preferredText;
  const fromPreferred = translateToolName(preferredText);
  if (fromPreferred) return fromPreferred;
  const fromId = translateToolName(raw);
  return fromId || preferredText || raw;
}

