/*
 * ══ 主题自由化（2026-10-02）：主题作者只往 themes/ 放文件，不改源码 ══
 * 契约（与 src 侧逐字一致）：一个主题 = themes/<id>.json（或 .theme.txt）+ 可选 themes/<id>.css
 *   colors 的每个键 K（值 V）→ CSS 变量 --kebab(K)（bg2→--bg-2、toolAccent→--tool-accent，与老变量名同一规则）
 *   uiStyle: S              → <html data-ui-style="S">（maid/pixel/mech 只是 S 恰好等于它的特例）
 *   image: F                → --theme-wallpaper: url("/api/themes/wallpaper?id=F")；没写 uiStyle 时形态名 = 'wallpaper'
 *   有伴生 CSS（主题对象的 css 字段为真）→ <link data-theme-css href="/api/themes/css?id=<id>">，切走即摘
 * config 只存 customThemeId，上面这些都只在 /api/themes 的主题对象上 → 前端缓存列表；
 * syncUiStyle 是同步的，只读缓存，缓存到了（boot / 打开设置）再整体重刷一次。
 */
const themeMetaById = new Map();
function rememberThemeMeta(list) {
  if (!Array.isArray(list)) return;
  themeMetaById.clear();
  for (const t of list) if (t && t.id) themeMetaById.set(String(t.id).toLowerCase(), t);
}
function currentThemeMeta(themeId) {
  const id = String(themeId !== undefined && themeId !== null ? themeId : (state?.config?.ui?.customThemeId || '')).toLowerCase();
  return id ? (themeMetaById.get(id) || null) : null;
}
/** 三内置形态判定：id 命中老集合优先（「形态优先」），其次主题自报 uiStyle 恰好是三者之一。 */
function builtinFormOf(id, meta) {
  if (MECH_UI_IDS.has(id)) return 'mech';
  if (MAID_UI_IDS.has(id)) return 'maid';
  if (PIXEL_UI_IDS.has(id)) return 'pixel';
  const st = String(meta?.uiStyle || '').trim().toLowerCase();
  return st === 'mech' || st === 'maid' || st === 'pixel' ? st : '';
}
function isBuiltinFormActive() {
  const a = document.documentElement.getAttribute('data-ui-style');
  return a === 'mech' || a === 'maid' || a === 'pixel';
}
function isBuiltinFormId(id) {
  const k = String(id || '').toLowerCase();
  return MECH_UI_IDS.has(k) || MAID_UI_IDS.has(k) || PIXEL_UI_IDS.has(k);
}
/** 主题有没有「首屏不拉列表就不知道」的东西 —— 有才值得拉完列表后重刷一次。 */
function themeMetaMatters(meta) {
  if (!meta) return false;
  if (meta.uiStyle || meta.image || meta.css || meta.hasCss) return true;
  return Object.keys(meta.colors || {}).some((k) => !LEGACY_COLOR_KEYS.has(k));
}
const UI_STYLE_NAME_RE = /^[A-Za-z0-9][A-Za-z0-9_-]{0,47}$/;
const THEME_COLOR_KEY_RE = /^[A-Za-z][A-Za-z0-9_-]{0,47}$/;
/** 老五色走 applyCustomColors 的既有管线（变量名与观感是现网契约，原样保留）。 */
const LEGACY_COLOR_KEYS = new Set(['bg', 'bg2', 'accent', 'text', 'toolAccent']);
/** 后三色同样有专门管线（推导兜底 + 亮度基准），不进「任意键」循环。 */
const MANAGED_COLOR_KEYS = new Set([...LEGACY_COLOR_KEYS, 'bg3', 'muted', 'faint']);
function colorKeyToCssVar(k) {
  return '--' + String(k)
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .replace(/([A-Za-z])(\d+)/g, '$1-$2')
    .replace(/_/g, '-')
    .toLowerCase();
}
function isCssColorValue(v) {
  const s = String(v || '').trim();
  if (!s) return false;
  try {
    if (typeof CSS !== 'undefined' && typeof CSS.supports === 'function') return CSS.supports('color', s);
  } catch { /* 走正则兜底 */ }
  return /^#(?:[0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(s)
    || /^(?:rgb|rgba|hsl|hsla|hwb|lab|lch|oklab|oklch|color-mix)\(/i.test(s)
    || /^[a-z]+$/i.test(s);
}
/** 能直接塞进 CSS 变量的值：拒绝能逃出声明或远程拉资源的写法（url / @import / 花括号 / 分号）。 */
function isSafeCssVarValue(v) {
  const s = String(v ?? '');
  return !!s.trim() && s.length <= 200 && !/[;{}<>\\]|url\s*\(|@import|expression\s*\(/i.test(s);
}
/** 当前自定义主题文件里声明的颜色（三内置形态 / 非自定义主题 → 空）。 */
function declaredThemeColors(cfg) {
  if (getThemePref() !== 'custom') return {};
  const id = String((cfg || state?.config)?.ui?.customThemeId || '').toLowerCase();
  if (!id || isBuiltinFormId(id)) return {};
  const meta = themeMetaById.get(id);
  if (!meta || builtinFormOf(id, meta)) return {};
  return meta.colors && typeof meta.colors === 'object' ? meta.colors : {};
}
/** 用户对当前主题「任意键」的改色（设置页动态色板写入）：config.ui.customExtraColors[<id>] = { 键: 值 }。 */
function readExtraColorOverrides(themeId) {
  const id = String(themeId || state?.config?.ui?.customThemeId || '');
  const fromCfg = state?.config?.ui?.customExtraColors;
  if (fromCfg && typeof fromCfg === 'object' && fromCfg[id] && typeof fromCfg[id] === 'object') return { ...fromCfg[id] };
  try {
    const raw = JSON.parse(localStorage.getItem('qqa-extra-colors') || 'null');
    if (raw && raw[id] && typeof raw[id] === 'object') return { ...raw[id] };
  } catch { /* ignore */ }
  return {};
}
/** 本轮生效的「任意键」颜色：主题声明 ∪ 用户改色（不含老五色 / 后三色，它们有专门管线）。 */
function effectiveExtraColors() {
  const out = {};
  const declared = declaredThemeColors(state?.config);
  if (!Object.keys(declared).length) return out;
  const merged = { ...declared, ...readExtraColorOverrides() };
  for (const [k, v] of Object.entries(merged)) {
    if (MANAGED_COLOR_KEYS.has(k) || !THEME_COLOR_KEY_RE.test(k)) continue;
    if (!isSafeCssVarValue(v)) continue;
    out[k] = String(v).trim();
  }
  return out;
}
let appliedThemeExtraVars = [];
function clearThemeExtraVars() {
  const root = document.documentElement;
  for (const name of appliedThemeExtraVars) root.style.removeProperty(name);
  appliedThemeExtraVars = [];
}
function applyThemeExtraVars() {
  clearThemeExtraVars();
  if (getThemePref() !== 'custom' || isBuiltinFormActive()) return;
  const root = document.documentElement;
  for (const [k, v] of Object.entries(effectiveExtraColors())) {
    const name = colorKeyToCssVar(k);
    root.style.setProperty(name, v);
    appliedThemeExtraVars.push(name);
  }
}
function themeWallpaperCss(meta) {
  const f = String(meta?.image || '').trim();
  if (!f || f.length > 255 || !/^[^\\/:*?"<>|%]+\.(?:png|jpe?g|webp)$/i.test(f)) return '';
  return `url("/api/themes/wallpaper?id=${encodeURIComponent(f)}")`;
}
function syncThemeWallpaperVar(meta) {
  const root = document.documentElement;
  const wp = themeWallpaperCss(meta);
  if (wp) root.style.setProperty('--theme-wallpaper', wp);
  else root.style.removeProperty('--theme-wallpaper');
}
/** 伴生 CSS 的地址；主题对象没声明 css（或声明为假）= 没有，不发任何请求。 */
function themeCssHref(meta) {
  if (!meta || !meta.id) return '';
  if (!(meta.css || meta.hasCss)) return '';
  const ver = meta.cssVersion ?? meta.cssMtime ?? '';
  return `/api/themes/css?id=${encodeURIComponent(String(meta.id))}${ver !== '' && ver !== null ? `&v=${encodeURIComponent(String(ver))}` : ''}`;
}
/** 伴生 CSS 生命周期：同 href 不重复注入；切主题 / 关自定义 / 加载失败（文件消失）一律摘除。 */
function syncThemeCssLink(meta) {
  const href = themeCssHref(meta);
  let links = [];
  try { links = Array.from(document.querySelectorAll('link[data-theme-css]') || []); } catch { links = []; }
  if (href && links.length === 1 && links[0].getAttribute('href') === href) return;
  for (const l of links) { try { l.remove(); } catch { /* ignore */ } }
  if (!href) return;
  try {
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.setAttribute('data-theme-css', String(meta.id));
    link.setAttribute('href', href);
    link.onerror = () => { try { link.remove(); } catch { /* ignore */ } };
    (document.head || document.documentElement).appendChild(link);
  } catch { /* 注入失败不影响主题其余部分 */ }
}
/** 拉一次主题列表填缓存；当前主题有「首屏不知道」的东西才整体重刷（老主题 / 三形态不重刷）。 */
async function refreshThemeMeta(prefetched) {
  try {
    const r = prefetched || await api('/api/themes');
    if (!Array.isArray(r?.themes)) {
      // 「200 但没有 themes 字段」≠「主题列表是空的」：前者是接口形状问题，记下来并报一行日志。
      // 页面上那句话由 loadThemePresets 负责（同一个接口，它才是画这排预设的人）。
      state.themeMetaError = new Error('主题返回里没有 themes 数组（不是"没有主题"）');
      return;
    }
    state.themeMetaError = null;
    rememberThemeMeta(r.themes);
    if (getThemePref() !== 'custom') return;
    const id = String(state?.config?.ui?.customThemeId || '').toLowerCase();
    if (!id || isBuiltinFormId(id)) return;
    if (themeMetaMatters(themeMetaById.get(id))) applyTheme('custom');
  } catch (e) {
    // 离线/失败：继续用已有缓存是**对的**，但不能什么都不说 —— 记下错误 + 报一行日志，
    // 界面上「机甲/女仆/像素」那三颗内置预设会被 loadThemePresets 标注成"内置兜底，不是服务端清单"。
    state.themeMetaError = e;
    uiReport('theme-meta', `refreshThemeMeta 失败：${apiFailureText(e)}`);
  }
}

/**
 * 设置页「配色」区下半截：当前主题声明了几个（老五色以外的）键就渲染几个输入。
 * #rrggbb / #rgb → 色板；其它合法颜色（rgb()/hsl()/具名色）或非颜色值 → 文本框，
 * 免得把作者写的 rgba(...) / 渐变之类硬塞进 <input type=color> 弄坏。
 */
function themeExtraColorEditorHtml() {
  const id = String(state?.config?.ui?.customThemeId || '');
  const declared = declaredThemeColors(state?.config);
  const keys = Object.keys(declared).filter((k) => !LEGACY_COLOR_KEYS.has(k) && THEME_COLOR_KEY_RE.test(k));
  if (!keys.length) {
    return '<div class="hint">当前主题没有声明额外的颜色键。主题作者在 themes/&lt;id&gt;.json 的 colors 里写任意键（如 <code>sidebarBg</code>），这里就会出现对应色板，并以 <code>--sidebar-bg</code> 变量生效。</div>';
  }
  const cur = readCustomColors(state?.config);
  const over = readExtraColorOverrides(id);
  const rows = keys.map((k) => {
    const val = String((MANAGED_COLOR_KEYS.has(k) ? (cur[k] || declared[k]) : (over[k] ?? declared[k])) ?? '').trim();
    const varName = colorKeyToCssVar(k);
    const hex = /^#[0-9a-f]{6}$/i.test(val) ? val
      : (/^#[0-9a-f]{3}$/i.test(val) ? '#' + val.slice(1).split('').map((ch) => ch + ch).join('') : '');
    const isColor = isCssColorValue(val);
    const input = hex
      ? `<input type="color" data-color-key="${esc(k)}" value="${esc(hex)}" />`
      : `<input type="text" data-color-key="${esc(k)}" value="${esc(val)}" spellcheck="false" style="width:150px" />`;
    const note = isColor ? '' : ' <span class="muted">（非颜色值：原样写入变量）</span>';
    return `<label class="color-field" title="${esc(varName)}">${esc(k)}${note}
          ${input}
        </label>`;
  }).join('');
  return `<div class="settings-actions" style="margin-top:10px;gap:14px">${rows}
        <button class="btn btn-small" type="button" id="cfg-custom-extra-reset">恢复主题文件里的值</button>
      </div>
      <div class="hint">以上是主题「${esc(id)}」自己声明的颜色键，改动即预览并保存在本机配置里（不改主题文件）。</div>`;
}
/** 读动态色板 → 写回：bg3/muted/faint 进 customBg3/customMuted/customFaint，其余进 customExtraColors[<id>]。 */
function persistExtraColorEditor(box) {
  if (!state?.config?.ui) return;
  const id = String(state.config.ui.customThemeId || '');
  if (!id) return;
  const managedMap = { bg3: 'customBg3', muted: 'customMuted', faint: 'customFaint' };
  const patch = {};
  const extra = {};
  (box?.querySelectorAll?.('[data-color-key]') || []).forEach((el) => {
    const k = el.dataset.colorKey;
    const v = String(el.value || '').trim();
    if (managedMap[k]) { patch[managedMap[k]] = v; state.config.ui[managedMap[k]] = v; }
    else if (isSafeCssVarValue(v)) extra[k] = v;
  });
  const all = { ...(state.config.ui.customExtraColors || {}) };
  all[id] = extra;
  state.config.ui.customExtraColors = all;
  patch.customExtraColors = all;
  try { localStorage.setItem('qqa-extra-colors', JSON.stringify(all)); } catch { /* ignore */ }
  saveCustomColorsToStorage({ ...readCustomColors(state.config), bg3: state.config.ui.customBg3, muted: state.config.ui.customMuted, faint: state.config.ui.customFaint });
  applyTheme('custom');
  return patch;
}

function syncUiStyle(themeId, themePref) {
  const root = document.documentElement;
  // themePref 优先：applyTheme 切走 custom 时 localStorage 可能还没写完，
  // 若仍读 getThemePref() 会把机甲形态/字体一直卡住。
  const pref = themePref != null ? themePref : getThemePref();
  const id = String(
    themeId !== undefined && themeId !== null
      ? themeId
      : (state?.config?.ui?.customThemeId || '')
  ).toLowerCase();
  const meta = pref === 'custom' ? currentThemeMeta(id) : null;
  // 老主题（缓存里没有 / 没写 uiStyle）时 form 只由 id 集合决定 —— 与改动前三行判断等价
  const form = pref === 'custom' ? builtinFormOf(id, meta) : '';
  const mech = form === 'mech';
  const maid = form === 'maid';
  const pixel = form === 'pixel';
  if (mech) {
    root.setAttribute('data-ui-style', 'mech');
    const fx = state?.config?.ui?.mechFx;
    const on = fx === undefined || fx === null ? true : fx !== false;
    root.setAttribute('data-mech-fx', on ? 'on' : 'off');
    // 浅色 token：customText 若被改成深色会盖掉机甲白字
    const mc = THEME_PRESET_MECH.colors;
    root.style.setProperty('--text', mc.text);
    root.style.setProperty('--muted', mc.muted);
    root.style.setProperty('--faint', mc.faint);
    root.style.setProperty('--bg', mc.bg);
    root.style.setProperty('--bg-2', mc.bg2);
    root.style.setProperty('--bg-3', mc.bg3);
    root.style.setProperty('--accent', mc.accent);
    root.style.setProperty('--tool-accent', mc.toolAccent);
    syncTitleBarFromTheme();
  } else if (maid) {
    root.setAttribute('data-ui-style', 'maid');
    root.removeAttribute('data-mech-fx');
    // 立刻注入浅色 token，避免 applyCustomColors 用旧的深色 customText 覆盖
    const m = THEME_PRESET_MAID.colors;
    root.style.setProperty('--text', m.text);
    root.style.setProperty('--muted', m.muted);
    root.style.setProperty('--faint', m.faint);
    root.style.setProperty('--bg', m.bg);
    root.style.setProperty('--bg-2', m.bg2);
    root.style.setProperty('--bg-3', m.bg3);
    syncTitleBarFromTheme();
  } else if (pixel) {
    root.setAttribute('data-ui-style', 'pixel');
    root.removeAttribute('data-mech-fx');
    // 同款教训：customText 若是深色会盖掉主题浅字 → 启动/切换时锁 token
    const p = THEME_PRESET_PIXEL.colors;
    root.style.setProperty('--text', p.text);
    root.style.setProperty('--muted', p.muted);
    root.style.setProperty('--faint', p.faint);
    root.style.setProperty('--bg', p.bg);
    root.style.setProperty('--bg-2', p.bg2);
    root.style.setProperty('--bg-3', p.bg3);
    root.style.setProperty('--accent', p.accent);
    root.style.setProperty('--tool-accent', p.toolAccent);
    syncTitleBarFromTheme();
  } else {
    // 主题自报的任意形态名原样透出；没报但带壁纸 → 通用 'wallpaper'；都没有 → 与改动前一样摘掉
    const own = String(meta?.uiStyle || '').trim();
    if (own && UI_STYLE_NAME_RE.test(own)) root.setAttribute('data-ui-style', own);
    else if (themeWallpaperCss(meta)) root.setAttribute('data-ui-style', 'wallpaper');
    else root.removeAttribute('data-ui-style');
    root.removeAttribute('data-mech-fx');
  }
  // 壁纸变量只给非三形态（三形态有自己的硬编码底图）；伴生 CSS 三形态也可叠加
  syncThemeWallpaperVar(form ? null : meta);
  syncThemeCssLink(meta);
}

/** 应用主题到 <html>，并同步顶栏两颗按钮（主题循环 + 自定义开关）。 */
function applyTheme(pref) {
  const actual = resolveTheme(pref);
  // 先写 localStorage，再算 UI 形态，避免 syncUiStyle 读到旧的 custom
  try { localStorage.setItem('qqa-theme', pref); } catch { /* ignore */ }
  document.documentElement.setAttribute('data-theme', actual);
  if (actual !== 'custom') {
    syncUiStyle('', actual);
  } else {
    syncUiStyle(state?.config?.ui?.customThemeId, 'custom');
  }
  syncChaosLayers(actual === '?');
  // 自定义色只在 custom 主题下盖变量；其它主题清掉 inline style，回到经典 macOS
  if (actual === 'custom') {
    const cur = readCustomColors(state?.config);
    // 没存过自定义色时，用明显区别于暗色的起点，避免「开了没变化」
    applyCustomColors(
      hasCustomColors(cur)
        ? cur
        : customStartColors()
    );
  } else {
    applyCustomColors({ bg: '', bg2: '', accent: '', text: '', toolAccent: '' });
  }
  // 主题/自定义色变了 → 重取未缩放底色，再按当前亮度盖一层（不用 filter）
  themeBaseBg = null;
  captureThemeBaseBg();
  applyBrightness(getBrightnessPref());
  const btn = $('#theme-btn');
  if (btn) {
    const show = THEME_ICON[pref] || THEME_ICON.dark;
    btn.textContent = show;
    btn.title = pref === 'custom'
      ? '主题：自定义中（设置 → 桌面端可关闭）'
      : `主题：${THEME_LABEL[pref] || '暗色'}（点击切换）`;
  }
  // 顶栏只保留一颗主题按钮；清理历史残留的第二颗
  document.querySelectorAll('#custom-theme-btn').forEach((el) => el.remove());
  // 设置页主题格子：只标循环里的四项；custom 不在格子里
  const picker = $('#theme-picker');
  if (picker) {
    picker.querySelectorAll('[data-theme-opt]').forEach((x) => {
      x.classList.toggle('on', pref !== 'custom' && x.dataset.themeOpt === pref);
    });
  }
  const customBtn = $('#cfg-custom-toggle');
  if (customBtn) {
    const on = pref === 'custom';
    customBtn.classList.toggle('is-on', on);
    customBtn.classList.toggle('btn-primary', on);
    customBtn.textContent = on ? '自定义主题：开' : '自定义主题';
    customBtn.title = on ? '点击关闭自定义，回到暗色' : '点击启用自定义主题';
  }
  try {
    localStorage.setItem('qqa-theme', pref);
  } catch { /* 忽略 */ }

  // Windows 系统窗口按钮（— □ ×）图标色/底色跟主题 + 亮度走
  syncTitleBarFromTheme();
}

/* ── 「？」主题的 JS 层：VHS 覆盖层 + 点击爆粒子 ──
   CSS 管不了的就这两件需要一个真实 DOM 层（body 的 ::before/::after 已被占用）。
   主题切走即移除，零残留。 */
function syncChaosLayers(on) {
  let vhs = document.getElementById('chaos-vhs');
  if (on && !vhs) {
    vhs = document.createElement('div');
    vhs.id = 'chaos-vhs';
    vhs.innerHTML = '<div class="vhs-track"></div>';   // 白闪太刺眼已移除，只留扫描线+追踪误差带
    document.body.appendChild(vhs);
  } else if (!on && vhs) {
    vhs.remove();
  }
}

// 点击爆「？」粒子：只在「？」主题下生效（判断放点击时，不绑状态）
document.addEventListener('click', (e) => {
  if (document.documentElement.getAttribute('data-theme') !== '?') return;
  // 一次爆 3~5 个，方向随机（抽象 = 不统一）
  const n = 3 + Math.floor(Math.random() * 3);
  for (let i = 0; i < n; i++) {
    const el = document.createElement('span');
    el.className = 'chaos-pop';
    el.textContent = '？';
    el.style.left = `${e.clientX}px`;
    el.style.top = `${e.clientY}px`;
    el.style.setProperty('--dx', `${(Math.random() - 0.5) * 160}px`);
    el.style.setProperty('--dy', `${-40 - Math.random() * 90}px`);
    el.style.setProperty('--rot', `${(Math.random() - 0.5) * 540}deg`);
    el.style.fontSize = `${14 + Math.random() * 20}px`;
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 850);
  }
}, { passive: true });

/** 点击主题按钮：暗 → 亮 → 跟随系统 → ？ → 暗。自定义不在循环里。 */
async function cycleTheme() {
  const cur = getThemePref();
  const order = ['dark', 'light', 'system', '?'];
  const i = order.indexOf(cur);
  const next = cur === 'custom' ? 'dark' : (order[(i + 1) % order.length] || 'dark');
  if (next === '?' && !(await showConfirmModal({ head: '切换主题', text: '进入「？」混乱主题？', okText: '进入', cancelText: '取消' }))) return false;
  if (!await persistUiPatch({ theme: next })) return false;
  if (state?.config?.ui) state.config.ui.theme = next;
  // 只有服务端确认保存后才改 localStorage / 页面主题。
  applyTheme(next);
  return true;
}

/**
 * 设置页独立「自定义主题」开关：点一下立刻换肤，不依赖「保存设置」。
 * 颜色优先读设置里的色板（用户可能已改未保存），否则读配置/localStorage。
 */
function readColorsFromEditor() {
  const bg = $('#cfg-custom-bg')?.value;
  const bg2 = $('#cfg-custom-bg2')?.value;
  const ac = $('#cfg-custom-accent')?.value;
  const tx = $('#cfg-custom-text')?.value;
  const ta = $('#cfg-custom-tool-accent')?.value;
  // 色板没挂载或还是出厂默认空态时不算「用户改过」
  if (!bg && !ac && !tx) return null;
  return {
    bg: bg || '',
    bg2: bg2 || '',
    accent: ac || '',
    text: tx || '',
    toolAccent: ta || ''
  };
}

function collectCustomColorsForApply() {
  const edited = readColorsFromEditor();
  if (edited && (edited.bg || edited.accent || edited.text)) return edited;
  const stored = readCustomColors(state?.config);
  if (stored.bg || stored.accent || stored.text) return stored;
  return customStartColors();
}

async function toggleCustomTheme() {
  const on = getThemePref() === 'custom';
  if (on) {
    if (!await persistUiPatch({ theme: 'dark' })) return false;
    // 关闭自定义：立刻回默认暗色，并清掉机甲形态 + inline 配色
    try { localStorage.setItem('qqa-theme', 'dark'); } catch { /* ignore */ }
    if (state?.config?.ui) state.config.ui.theme = 'dark';
    document.documentElement.setAttribute('data-theme', 'dark');
    syncUiStyle('', 'dark');
    syncChaosLayers(false);
    applyCustomColors({ bg: '', bg2: '', accent: '', text: '', toolAccent: '' });
    themeBaseBg = null;
    captureThemeBaseBg();
    applyBrightness(getBrightnessPref());
    const btn = $('#theme-btn');
    if (btn) {
      btn.textContent = THEME_ICON.dark || THEME_ICON.dark;
      btn.title = '主题：暗色（点击切换）';
    }
    const customBtn = $('#cfg-custom-toggle');
    if (customBtn) {
      customBtn.classList.remove('is-on', 'btn-primary');
      customBtn.textContent = '自定义主题';
      customBtn.title = '点击启用自定义主题';
    }
    const picker = $('#theme-picker');
    if (picker) {
      picker.querySelectorAll('[data-theme-opt]').forEach((x) => {
        x.classList.toggle('on', x.dataset.themeOpt === 'dark');
      });
    }
    try { loadThemePresets(); } catch { /* 面板未挂载时忽略 */ }
    return true;
  }
  // 开启自定义：先保存，再写本地偏好并应用主题。
  const cur = collectCustomColorsForApply();
  const currentThemeId = state?.config?.ui?.customThemeId || '';
  const matchesMechPreset = (cur.bg || '').toLowerCase() === CUSTOM_START.bg.toLowerCase()
    || (cur.accent || '').toLowerCase() === (CUSTOM_START.accent || '').toLowerCase();
  const customThemeId = currentThemeId || (matchesMechPreset ? THEME_PRESET_MECH.id : '');
  const patch = {
    theme: 'custom',
    customBg: cur.bg,
    customBg2: cur.bg2,
    customAccent: cur.accent,
    customText: cur.text,
    customToolAccent: cur.toolAccent,
    customThemeId
  };
  if (!await persistUiPatch(patch)) return false;
  saveCustomColorsToStorage(cur);
  if (state?.config?.ui) Object.assign(state.config.ui, patch);
  applyTheme('custom');
  try { loadThemePresets(); } catch { /* ignore */ }
  return true;
}

async function api(path, options = {}) {
  const res = await fetch(path, {
    headers: {
      'content-type': 'application/json',
      'x-console-token': CONSOLE_MARKER,
      ...(options.headers || {})
    },
    ...options
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    const error = new Error(data.error || data.reason || `HTTP ${res.status}`);
    error.data = data;
    error.status = res.status;
    error.method = String(options.method || 'GET').toUpperCase();
    throw error;
  }
  return data;
}

/**
 * 接口失败的可见文案：后端原文 + HTTP 状态一起摊出来。
 * 「这次请求失败」和「确实没有数据」是两件事 —— 空数组是数据，抛错不是，
 * 页面不能拿空的去顶替失败的（用户会以为功能在、只是没内容）。
 */
function apiFailureText(error) {
  const status = Number(error?.status || 0);
  const raw = String(error?.data?.error ?? error?.data?.reason ?? error?.message ?? error ?? '未知错误');
  return status ? `${raw}（HTTP ${status}）` : raw;
}

/** API 显式返回 persisted 时，把服务端报告的写盘状态原样变成面板提示。 */
function persistedStatusText(result) {
  if (!Object.prototype.hasOwnProperty.call(result || {}, 'persisted')) return '';
  const persisted = result.persisted;
  if (persisted?.ok === true) return ' · 服务端确认已写入磁盘';
  if (persisted?.ok === false) return ` · 服务端未确认写盘：${String(persisted.error || 'persisted.ok=false')}`;
  return ' · 服务端返回了无法识别的写盘状态';
}

/** 保存 UI 即时设置；失败必须可见，并可回滚已做的本地预览。 */
async function persistUiPatch(patch, { rollback, previewMessage = '' } = {}) {
  try {
    const data = await api('/api/config', { method: 'POST', body: JSON.stringify({ ui: patch }) });
    if (data?.config) state.config = data.config;
    return true;
  } catch (error) {
    try { rollback?.(); } catch (rollbackError) {
      console.warn('[ui] 保存失败后的本地回滚也失败:', rollbackError);
    }
    const fallback = previewMessage || '本次设置未保存，已恢复到上次保存的状态。';
    showNoticeModal('保存失败', `${apiFailureText(error)}\n${fallback}`);
    return false;
  }
}

/** 数据块级别的降级文案（挂在页面里的一小块，不影响整页其余部分）。 */
function blockFailureHtml(title, error, extra = '') {
  return `<div class="fetch-fail" style="border:1px solid var(--orange);background:rgba(245,158,11,.10);
    border-radius:8px;padding:8px 12px;margin:6px 0;font-size:12px;line-height:1.8">
    <b>⚠ ${esc(title)}没拿到</b> —— ${esc(apiFailureText(error))}${extra ? `<br/><span style="color:var(--muted)">${esc(extra)}</span>` : ''}
  </div>`;
}

/**
 * 页面级兜底：容器还空着（这一次加载前从没画过）时，把失败原因画进去。
 * 已经有内容就不动 —— 轮询偶发失败不该抹掉用户正在看（甚至正在编辑）的页面。
 */
function paintFailureIfEmpty(box, error, title) {
  if (!box || String(box.innerHTML || '').trim()) return false;
  box.innerHTML = `<div class="page-fail" style="border:1px solid var(--red);background:rgba(239,68,68,.10);
    border-radius:8px;padding:12px 14px;margin:12px 0;font-size:13px;line-height:1.8">
    <b>⚠ ${esc(title)} —— 页面没能画出来</b><br/>
    <span style="color:var(--muted)">${esc(apiFailureText(error))}</span>
  </div>`;
  return true;
}

/**
 * 文本版 setHtmlIfChanged：**内容没变就不写 DOM**。
 * 顶栏那几颗字是被 4s/15s 轮询反复刷的 —— 无条件 textContent= 等于每轮都重排一次，
 * 失败状态下还会把"降级提示"一遍遍重写（闪、抢焦点）。写之前比一次，等价就不碰。
 */
function setTextIfChanged(el, text) {
  if (!el) return false;
  const next = String(text ?? '');
  if (el.textContent === next) return false;
  el.textContent = next;
  return true;
}

/**
 * 前端异常上报：把渲染器里的报错送到后端日志（`/api/ui-log`）。
 *
 * 为什么要有（2026-10-03 实测）：换人设 / 保存人设失败时，服务端日志干干净净、
 * 浏览器控制台才看得到异常 —— 用户说"点了没作用"，我们只能猜。现在凡是有异常、
 * 或者关键步骤走偏，都会在 App 日志里留一行 `[ui:xxx]`。
 */
function uiReport(tag, message) {
  try {
    void fetch('/api/ui-log', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ tag: String(tag || 'ui'), message: String(message ?? '').slice(0, 500) })
    }).catch(() => { /* 上报失败绝不能影响主流程 */ });
  } catch { /* 同上 */ }
}
try {
  window.addEventListener('error', (e) => {
    uiReport('error', `${e?.message || 'error'} @${e?.filename || '?'}:${e?.lineno || 0}`);
  });
  window.addEventListener('unhandledrejection', (e) => {
    const reason = e?.reason;
    uiReport('reject', reason?.message || String(reason || 'unhandledrejection'));
    // ★ N55（2026-10-10）：「点了没作用」的一类根因 —— 点击处理里 `await api(...)` 抛了却没人接。
    //   老树每个出口都在，新树有几组还是 notPorted（501），于是按钮按下去只剩后端日志，屏幕上不长东西。
    //   只弹**写操作**（POST/PUT/DELETE）的 HTTP 失败：轮询都是 GET，网络抖动不该弹窗；
    //   已经开着弹窗时也不叠加（一个用户动作最多一次打扰）。
    if (!reason?.status || reason.method === 'GET') return;
    if (document.querySelector('.model-modal-overlay')) return;
    showNoticeModal('这一步没做成', `${apiFailureText(reason)}\n这次操作没有生效，界面保持原样。`);
  });
} catch { /* 环境不支持就算了 */ }

function fmtTime(ts) {
  if (!ts) return '-';
  const d = new Date(ts);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}

function fmtClock(ts) {
  const d = new Date(ts);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
}

function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

/**
 * 链接地址的协议闸门：抓来的/服务端给的/草稿里存的地址，只认 http(s)（以及站内相对路径）。
 * `esc()` 只挡引号逃逸，挡不住 `javascript:` / `data:` 本身 —— 点一下就在本站原点执行。
 * 判定不了就不渲染成链接，退回纯文本，绝不"先信了再说"。
 */
function safeHref(url) {
  const raw = String(url ?? '').trim();
  if (!raw) return '';
  if (/^https?:\/\//i.test(raw)) return raw;
  if (/^\/(?!\/)/.test(raw)) return raw;   // 站内相对路径（如 /api/themes/css?id=…）
  return '';
}

/**
 * 图片地址的闸门：`<img src>` 允许 http(s) / blob / 站内相对路径，以及 image/* 的 dataURL。
 * 相对路径**照放**（图库缩略图里有一批服务端返回的裸路径，卡协议会把它们画没），
 * 只挡带危险协议的（javascript: / file: / data:text/html …）。
 */
function safeImgSrc(url) {
  const raw = String(url ?? '').trim();
  if (!raw) return '';
  if (/^data:image\/(png|jpe?g|gif|webp|avif|bmp);base64,/i.test(raw)) return raw;
  if (/^(https?|blob):/i.test(raw)) return raw;
  if (/^[a-z][a-z0-9+.-]*:/i.test(raw)) return '';   // 带别的协议 ⇒ 拒
  return raw;                                        // 无协议 = 相对路径
}

// W-3b(2)：状态/追踪/账本的词表**只有 apps/ui/status-vocab.js 那一份**（全树唯一）。
// 这里过去是一张 6 个词的本地小表 + `|| s.status` 兜底 ⇒ 盘上真出现过的
// `completed / delivered / skip / stopped / waiting…` 有半数不在表里，兜底把**英文原词**直接印上胶囊
// （主人报的"状态胶囊看不懂"就是这个）。现在：
//   · 词表外的值 ⇒ 原词 + 「未登记」角标（看得见、不猜）
//   · 一条都没发出去 ⇒ 「未发送」，绝不显示成正常结束
// 词表文件没 load 上来（异常/漏改 index.html）⇒ 每个值都按「未登记」显示，宁可满屏红也不装绿。
const VOCAB = globalThis.STATUS_VOCAB ?? null;
function capsuleFor(s) {
  if (VOCAB?.sessionStatusHtml) return VOCAB.sessionStatusHtml(s);
  return {
    label: `${esc(s?.status ?? '无状态')}<span class="vocab-unregistered">词表未加载</span>`,
    tone: 'orange',
    statusClass: `status-${s?.status ?? 'unknown'} vocab-unregistered`,
    undelivered: false,
    info: {},
  };
}
function vocabLabel(info) {
  const label = esc(info?.label ?? '');
  if (info?.known === false && info?.raw) return `${label}<span class="vocab-unregistered" title="这个词没登记进面板词表：不要当成成功">未登记</span>`;
  return label;
}
function vocabLookup(table, value, emptyLabel) {
  if (!VOCAB?.tables?.[table]) return { label: String(value ?? emptyLabel ?? ''), tone: 'orange', known: false, raw: String(value ?? '') };
  return VOCAB.lookup(VOCAB.tables[table], value, emptyLabel);
}

/**
 * ★ P1-a：**SSE 帧不带结果三键**（帧由编排层的 `sessionFramePayload` 构造，不在面板地盘）
 *   ⇒ 一轮从"还在跑"翻成终态的那一刻，手上那份派生结论**必然过期**。
 *   这里只做一件事：**作废**它（置空 ⇒ 胶囊/结论显示「没记」），等 `session-end` 重拉详情或列表轮询
 *   把服务端算好的权威值补回来。**不许**在 UI 侧另算一套判据去"补"上 —— 那正是答复点名的重复故障。
 * @returns {object} 需要覆盖的键（非终态、或本来就没有旧结论 ⇒ 空对象，什么都不动）
 */
const TERMINAL_SESSION_STATUSES = new Set(['done', 'delivered', 'completed', 'noreply', 'skip', 'skipped', 'wait', 'stopped', 'aborted', 'error', 'empty']);
function terminalStatusPatch(status, previous) {
  const s = String(status ?? '');
  if (!TERMINAL_SESSION_STATUSES.has(s)) return {};
  if (!String(previous?.replyOutcome ?? '') && !String(previous?.replyReason ?? '') && !String(previous?.toolOutcome ?? '')) return {};
  return { replyOutcome: '', replyReason: '', toolOutcome: '' };
}


// ── 启动 loading 壳：页面先渲染，等服务可用后自动隐藏 ──
const loadingOverlay = $('#loading-overlay');
const loadingStatus = $('#loading-status');
const loadingLogs = $('#loading-logs');
let appReady = false;
let bootLogs = [];

function setLoadingStatus(text) {
  bootLogs.push(`[${new Date().toLocaleTimeString('zh-CN', { hour12: false })}] ${text}`);
  if (loadingStatus) loadingStatus.textContent = text;
  if (loadingLogs) loadingLogs.textContent = bootLogs.slice(-12).join('\n');
}

function hideLoading() {
  appReady = true;
  if (loadingOverlay) {
    loadingOverlay.style.transition = 'opacity .25s ease';
    loadingOverlay.style.opacity = '0';
    setTimeout(() => { loadingOverlay?.remove(); }, 300);
  }
}

async function pollUntilReady() {
  const startedAt = Date.now();
  try {
    const status = await api('/api/status');
    if (!status.onebot?.connected) setLoadingStatus('SnowLuma 已就绪，正在连接 OneBot…');
    else setLoadingStatus(`OneBot 已连接${status.onebot.self ? `（${status.onebot.self.nickname}）` : ''}，即将进入控制台…`);
    // 服务已可达，无需等到 OneBot 完全连上即可进入控制台（体检卡会继续提示）
    return true;
  } catch (e) {
    if (Date.now() - startedAt > 45000) {
      setLoadingStatus('启动超时。请确认项目内 snowluma 文件夹完整，或到设置页手动启动 SnowLuma。');
      return false;
    }
    return false;
  }
}

async function bootLoop() {
  for (let i = 0; i < 90; i++) {
    if (await pollUntilReady()) break;
    await new Promise((r) => setTimeout(r, 1000));
  }
  hideLoading();
  refreshStatus();
  // ★ Minimax/U6：这里原来也是裸调 loadSessions()，而 DOM ready 那段（文件末尾）也调了一次
  //   ⇒ 开窗头一秒内连发两次 /api/sessions。
  //   判据用 `sessionLastRefreshAt`：DOM ready 那次已经跑过（或正在跑）就别再排一次。
  //   （U3 只把这一处改成了"走调度器"，调度器只挡"并发"，不挡"稍后再来一次" ⇒ 第二次照样发出去。
  //    U6 实测首屏仍发两次，加这个判据才真正只剩一次。）
  if (state.tab === 'sessions' && sessionLastRefreshAt === 0) scheduleSessionEventRefresh();
  if (state.tab === 'memory') loadMemoryView();
}

// ── 就绪度体检（傻瓜式引导的核心） ──
function assessReadiness(cfg, status) {
  const checks = [];
  if (!cfg) return { ready: false, checks: [{ ok: false, label: '配置加载失败' }] };
  // 拆成"接口地址"与"模型"两步：合并判断时新手分不清到底缺哪个。
  // 出厂 baseUrl 为空，第一条会直接指出该填什么。
  const urlOk = !!String(cfg.api.baseUrl || '').trim();
  checks.push({
    ok: urlOk,
    label: urlOk ? `接口地址：${cfg.api.baseUrl}` : '还没有填接口地址（Base URL，必填）：官方 API 或中转站提供的 OpenAI 兼容地址',
    fix: urlOk ? null : 'settings-api'
  });
  const modelOk = !!String(cfg.api.model || '').trim();
  checks.push({
    ok: modelOk,
    label: modelOk ? `模型已选择：${cfg.api.model}` : '还没有选择模型（填好地址后点「获取列表」或手动添加）',
    fix: modelOk ? null : 'settings-api'
  });
  const allowOk = (cfg.allow?.groups?.length || cfg.allow?.private?.length || cfg.allowAllWhenEmpty);
  checks.push({ ok: !!allowOk, label: allowOk ? `白名单：${(cfg.allow.groups || []).length} 个群 / ${(cfg.allow.private || []).length} 个好友` : '还没有配置白名单（必填）', fix: allowOk ? null : 'settings-allow' });
  const obOk = status?.onebot?.connected;
  checks.push({ ok: !!obOk, label: obOk ? `OneBot 已连接${status.onebot.self ? `（${status.onebot.self.nickname}）` : ''}` : 'OneBot（SnowLuma）未连接 —— 请到 QQ 连接页签启动', fix: obOk ? null : 'snowluma-tab' });
  return { ready: urlOk && modelOk && allowOk && obOk, checks };
}

/** 内容没变就不写 innerHTML，避免定时/SSE 反复整页重绘。返回是否真的写入。 */
function setHtmlIfChanged(el, html) {
  if (!el) return false;
  if (el.dataset.sig === html) return false;
  el.innerHTML = html;
  el.dataset.sig = html;
  return true;
}

// 密钥框里的这串只是"已保存"的记号，不是值。服务端 deepMerge 对空串照样覆盖，
// 所以前端在任何一次落盘里都不能送出 ''，也不能送出这串占位。
const SECRET_BOX_PLACEHOLDER = '******';

/** 密钥框显示值：编辑中的草稿优先；否则有 has* 标记就显示占位，永不显示真实值。 */
function secretInputValue(hasSaved, draft = null) {
  if (typeof draft === 'string') return draft;
  return hasSaved ? SECRET_BOX_PLACEHOLDER : '';
}

/** 这个密钥键要不要带上：未编辑 / 留空 / 仍是占位 → undefined，调用方整键不带。 */
function secretFieldValue(raw) {
  const value = String(raw ?? '').trim();
  return value && value !== SECRET_BOX_PLACEHOLDER ? value : undefined;
}

/** 桥上账号白名单卡片的落盘补丁（纯函数，测试单独跑它）。 */
function bridgePatch({ saved = {}, uins, autoUnhook, webuiPassword }) {
  const pw = secretFieldValue(webuiPassword);
  return {
    ...saved,
    accountWhitelist: [...uins],
    autoUnhookStrangers: !!autoUnhook,
    ...(pw === undefined ? {} : { webuiPassword: pw })
  };
}

function renderBanner() {
  const banner = $('#banner');
  const s = state.status;
  let show = false;
  let html = '';
  // 预算保险丝已移除：原先这里有一个 pauseReason === 'budget' 的分支
  if (state.paused) {
    show = true;
    html = '⏸ 机器人已暂停，不会处理任何消息。';
  } else if (s?.onebot?.warning) {
    // 例如：连上的其实是另一份副本/另一个实例的 SnowLuma（同一个 QQ 号会被两个实例抢着回）
    show = true;
    html = `⚠ ${esc(s.onebot.warning)}`;
  } else if (s?.snowluma?.warning) {
    // 桥上挂了白名单之外的号（典型：SnowLuma 自动注入把管理员自己的号也挂上了）
    show = true;
    html = `⚠ ${esc(s.snowluma.warning)}`;
  } else if (s?.onebot && !s.onebot.connected && !s.onebot.everConnected) {
    // ↑ 必须有 onebot 这个字段才敢下"还没连上"这句断言；字段缺失走顶栏那句「状态缺 onebot 字段」，
    //   这里以前写成 `s && !s.onebot.connected` ⇒ 200 但少字段时抛 TypeError，被上层 catch 报成"状态未取到"
    show = true;
    html = '🔌 OneBot（SnowLuma）还没连上：请确认 SnowLuma 已启动，且设置里的 WS/HTTP 地址正确。';
  }
  banner.classList.toggle('hidden', !show);
  if (!show) {
    banner.dataset.sig = '';
    return;
  }
  if (state.paused) {
    html += ` <button class="btn btn-small" id="banner-resume-btn">恢复</button>
      <button class="btn btn-small btn-danger" id="banner-resume-read-btn" title="恢复运行，并把暂停期间积压的所有未读消息直接标记为已读（不再处理）">恢复并全部标为已读</button>`;
  }
  if (!setHtmlIfChanged(banner, html)) return;
  const link = $('#banner-goto-settings');
  if (link) link.addEventListener('click', (e) => { e.preventDefault(); switchTab('settings'); });
  const resumeBtn = $('#banner-resume-btn');
  if (resumeBtn) resumeBtn.addEventListener('click', () => resumePause({ skipBacklog: false }));
  const resumeReadBtn = $('#banner-resume-read-btn');
  if (resumeReadBtn) resumeReadBtn.addEventListener('click', () => resumePause({ skipBacklog: true }));
}

async function resumePause({ skipBacklog = false } = {}) {
  try {
    if (skipBacklog) {
      await api('/api/pause', { method: 'DELETE', body: '{}' });
    } else {
      await api('/api/pause', { method: 'POST', body: JSON.stringify({ paused: false }) });
    }
    await refreshStatus();
    if (state.tab === 'chats') loadChats({ quiet: true });
  } catch (e) {
    // ★ N66（2026-10-10）：改前只 console.error ⇒ 用户点横幅上的「恢复」/「恢复并全部标为已读」
    //   失败时页面一动不动（横幅还在），只在控制台里留一行 —— 典型的"点了没作用"。
    //   /api/pause 的返回不能保证状态变了 ⇒ 这里只说"可能没变"，不假装成功。
    showNoticeModal('恢复运行没成功', `${apiFailureText(e)}\n机器人状态可能没变，可以再点一次。`);
  }
}

/**
 * 按配置显隐「免费API」页签。
 * 隐藏规则：ui.hideApiNews === true，或后台抓取被关掉（apiNews.enabled === false）。
 * 隐藏时若正停在该页，自动切回会话页，避免停在看不见的视图上。
 */
function applyApiNewsVisibility(cfg = state.config) {
  const ui = cfg?.ui || {};
  const apiCfg = cfg?.webSearch?.apiNews || {};
  const hide = ui.hideApiNews === true || apiCfg.enabled === false;
  const tab = $$('.tab').find((t) => t.dataset.tab === 'apinews');
  if (tab) {
    tab.hidden = hide;
    tab.style.display = hide ? 'none' : '';
  }
  if (hide && state.tab === 'apinews') switchTab('sessions');
  return hide;
}

