      const text = String(overlay.querySelector('#kb-edit-text')?.value || '').trim();
      if (!text) { msg.textContent = '内容不能为空。'; return; }
      const tags = String(overlay.querySelector('#kb-edit-tags')?.value || '').split(/[,，、]/).map((s) => s.trim()).filter(Boolean);
      const note = String(overlay.querySelector('#kb-edit-note')?.value || '').trim();
      try {
        const r = await api('/api/memes', { method: 'POST', body: JSON.stringify({ text: text.slice(0, 120), tags, note: note.slice(0, 120), kind: entry.kind || 'meme' }) });
        if (!r?.ok) { msg.textContent = r?.error || '保存失败'; return; }
        closeModelModal(overlay);
        showUploadToast('已更新', text.slice(0, 40));
      } catch (e) { msg.textContent = `保存失败：${e?.message || e}`; }
