/** 自定义搜索源是高级管理操作：在开发者页维护，provider 下拉仍留在设置页。 */
function renderDevSearchProviderManagerHtml() {
  const providers = Array.isArray(state.config?.webSearch?.providers) ? state.config.webSearch.providers : [];
  const selected = String(state.config?.webSearch?.provider || '');
  const selectedCustom = selected.startsWith('custom:');
  return `
    <div class="form-field" id="custom-provider-manage" style="${selectedCustom ? '' : 'opacity:.72'};margin-bottom:12px">
      <label><span class="ff-lab">当前自定义搜索服务</span><span class="ff-unit">先在「设置 → 搜索服务」选择自定义源</span></label>
      <div class="field-addon" style="flex-wrap:wrap">
        <button class="btn btn-small" id="test-search-provider-btn" type="button">测试这个搜索服务</button>
        <button class="btn btn-small btn-danger" id="del-search-provider-btn" type="button">删除这个搜索服务</button>
        <span id="search-provider-action-hint" class="muted" style="font-size:12px">${selectedCustom ? esc(providers.find((p) => `custom:${p.id}` === selected)?.name || '已选择自定义源') : '当前未选择自定义源'}</span>
      </div>
    </div>
    <div class="form-grid cols-2">
      ${ffText('new-sp-name', '名称', '自己辨认用', '', 'placeholder="例如：自建 SearXNG"')}
      ${ffSelect('new-sp-type', '类型', '接口风格',
        `<option value="openai">JSON 搜索接口（POST）</option><option value="bing">网页解析（Bing 结果格式）</option>`)}
    </div>
    ${ffText('new-sp-baseurl', '接口地址 / 搜索页地址', 'JSON 或网页搜索地址', '',
      'placeholder="JSON：https://your-search.example.com/search；网页：https://your-searx.example.com/search"')}
    <div class="form-grid cols-2">
      ${ff('new-sp-apikey', 'API Key', '可选 · 多数自建留空',
        `<input type="password" id="new-sp-apikey" placeholder="多数自建服务留空即可" autocomplete="new-password" />`)}
      ${ffText('new-sp-model', '模型名', '可选 · Responses API 才需要', '', 'placeholder="可选"')}
    </div>
    <div class="settings-actions">
      <button class="btn btn-small" id="add-search-provider-btn" type="button">＋ 添加并选中</button>
      <span id="add-search-provider-hint" class="muted" style="font-size:12px"></span>
    </div>`;
}

function bindDevSearchProviderActions(root) {
  root.querySelector('#add-search-provider-btn')?.addEventListener('click', async () => {
    const hint = root.querySelector('#add-search-provider-hint');
    const baseUrl = (root.querySelector('#new-sp-baseurl')?.value || '').trim();
    if (!baseUrl) { if (hint) hint.textContent = '请先填接口地址'; return; }
    if (hint) hint.textContent = '添加中…';
    try {
      const r = await api('/api/search-providers', {
        method: 'POST',
        body: JSON.stringify({
          name: (root.querySelector('#new-sp-name')?.value || '').trim(),
          type: root.querySelector('#new-sp-type')?.value || 'openai',
          baseUrl,
          apiKey: (root.querySelector('#new-sp-apikey')?.value || '').trim(),
          model: (root.querySelector('#new-sp-model')?.value || '').trim()
        })
      });
      await api('/api/config', {
        method: 'POST',
        body: JSON.stringify({ webSearch: { provider: `custom:${r.provider.id}` } })
      });
      for (const id of ['#new-sp-name', '#new-sp-baseurl', '#new-sp-apikey', '#new-sp-model']) {
        const el = root.querySelector(id);
        if (el) el.value = '';
      }
      await loadSettings();
      if (state.tab === 'devmode') renderDevModePage();
      const currentHint = $('#add-search-provider-hint');
      if (currentHint) currentHint.textContent = `已添加并选中自定义搜索源${persistedStatusText(r)}`;
    } catch (error) {
      if (hint) hint.textContent = `添加失败：${error.message}`;
    }
  });

  root.querySelector('#test-search-provider-btn')?.addEventListener('click', async () => {
    const hint = root.querySelector('#search-provider-action-hint');
    const providerId = String(state.config?.webSearch?.provider || '');
    if (!providerId.startsWith('custom:')) { if (hint) hint.textContent = '请先到「设置 → 搜索服务」选择一个自定义搜索服务'; return; }
    if (hint) hint.textContent = '测试中…';
    try {
      const r = await api('/api/search-providers/test', {
        method: 'POST', body: JSON.stringify({ providerId })
      });
      const result = r.result || {};
      if (hint) hint.textContent = result.ok
        ? `✓ 可用（${result.count} 条结果，${result.latencyMs}ms）${result.sample ? `：${result.sample.slice(0, 30)}` : ''}`
        : `✗ ${result.note || '不可用'}`;
    } catch (error) {
      if (hint) hint.textContent = `测试失败：${error.message}`;
    }
  });

  root.querySelector('#del-search-provider-btn')?.addEventListener('click', async () => {
    const hint = root.querySelector('#search-provider-action-hint');
    const providerId = String(state.config?.webSearch?.provider || '');
    // ★ N66：内置源（bing/google…）没有可删的自定义条目，改前直接 return ⇒ 点「删除」毫无反应。
    //   拒得很对，但不该瞒着用户拒 ⇒ 把原因写在同一行的提示里。
    if (!providerId.startsWith('custom:')) {
      if (hint) hint.textContent = '当前选的是内置搜索源，没有可删除的条目（只有「自定义」源能删）';
      return;
    }
    const id = providerId.slice('custom:'.length);
    const name = state.config?.webSearch?.providers?.find((p) => p.id === id)?.name || id;
    if (!(await showConfirmModal({ head: '删除搜索服务', text: `确定删除搜索服务「${name}」？`, danger: true, okText: '删除', cancelText: '取消' }))) return;
    try {
      const result = await api('/api/search-providers', { method: 'DELETE', body: JSON.stringify({ id }) });
      await loadSettings();
      if (state.tab === 'devmode') renderDevModePage();
      const currentHint = $('#search-provider-action-hint');
      if (currentHint) currentHint.textContent = `已删除自定义搜索源「${name}」${persistedStatusText(result)}`;
    } catch (error) {
      if (hint) hint.textContent = `删除失败：${apiFailureText(error)}`;
      alert(`删除失败：${error.message}`);
    }
  });
}

function bindDevBrowseControls(root) {
  const domains = root.querySelector('#dev-browse-domains');
  const paste = root.querySelector('#dev-browse-paste');
  const hint = root.querySelector('#dev-browse-hint');
  const addDomain = () => {
    const host = normalizeDomain(paste?.value || '');
    if (!host) {
      if (hint) hint.textContent = '没识别出站点，检查一下网址（例：https://zh.wikipedia.org/wiki/猫）';
      return;
    }
    const lines = String(domains?.value || '').split('\n').map((x) => x.trim()).filter(Boolean);
    if (!lines.some((line) => normalizeDomain(line) === host)) lines.push(host);
    if (domains) domains.value = lines.join('\n');
    if (paste) paste.value = '';
    if (hint) hint.textContent = `已加入 ${host}（点「保存改动」后生效）`;
  };
  root.querySelector('#dev-browse-add')?.addEventListener('click', addDomain);
  paste?.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') { event.preventDefault(); addDomain(); }
  });
  const search = root.querySelector('#dev-browse-search-url');
  const searchHint = root.querySelector('#dev-browse-search-hint');
  if (search && searchHint) {
    const sync = () => {
      const template = String(search.value || '').trim();
      if (!template) { searchHint.textContent = '留空 = 自动给关键词加 site:你的站点限定（Bing 支持）。'; return; }
      const hasToken = SEARCH_PLACEHOLDERS.some((token) => template.includes(token));
      searchHint.innerHTML = `搜「猫」时会抓：<code>${esc(buildSiteSearchPreview(template, '猫'))}</code>`
        + (hasToken ? '' : '<br><b>⚠️ 没找到 {query} 这类占位符</b>——建议在地址中直接写 {query}。');
    };
    search.addEventListener('input', sync);
    sync();
  }
}

